1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      /* The color is the content here, so keep it; the stroke guarantees the shape */
60	      .circle svg {
61	        forced-color-adjust: none;
62	        color: var(--fg);
63	      }
64	      svg circle {
65	        stroke: CanvasText;
66	        stroke-width: 2;
67	      }
68	    }
69	    body {
70	      min-height: 100vh;
71	      min-height: 100dvh;
72	      display: grid;
73	      place-items: center;
74	      padding: 1rem;
75	      background: var(--bg);
76	      color: var(--text);
77	      font-family: system-ui, -apple-system, sans-serif;
78	    }
79	    main {
80	      width: 100%;
81	      display: flex;
82	      flex-direction: column;
83	      align-items: center;
84	      text-align: center;
85	    }
86	    .circle {
87	      display: block;
88	      width: min(360px, 100%, 60vh);
89	      width: min(360px, 100%, 60dvh);
90	      aspect-ratio: 1;
91	      border: 0;
92	      border-radius: 50%;
93	      background: none;
94	      color: var(--fg);
95	      cursor: pointer;
96	      touch-action: manipulation;
97	      -webkit-tap-highlight-color: transparent;
98	      -webkit-user-select: none;
99	      user-select: none;
100	      -webkit-touch-callout: none;
101	      transition: color 0.4s;
102	      min-height: 48px;
103	      min-width: 48px;
104	    }
105	    .no-transition,
106	    .no-transition svg {
107	      transition: none !important;
108	    }
109	    .circle:focus-visible {
110	      outline: 3px solid currentColor;
111	      outline-offset: 12px;
112	    }
113	    svg {
114	      display: block;
115	      width: 100%;
116	      height: 100%;
117	      overflow: visible;
118	      /* Leave hit testing to the button's rounded box, not the svg's square one */
119	      pointer-events: none;
120	      opacity: 0.85;
121	      filter: var(--drop);
122	      transition: opacity 0.3s;
123	    }
124	    .circle:active svg,
125	    .circle:focus-visible svg {
126	      opacity: 1;
127	    }
128	    @keyframes pulse {
129	      0% {
130	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
131	      }
132	      100% {
133	        filter: var(--drop) drop-shadow(0 0 0 transparent);
134	      }
135	    }
136	    @media (hover: hover) {
137	      .circle:hover svg {
138	        opacity: 1;
139	      }
140	    }
141	    @media (prefers-reduced-motion: no-preference) {
142	      svg {
143	        transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.3s;
144	      }
145	      .circle:focus-visible svg {
146	        transform: scale(1.05);
147	      }
148	      .circle:active svg {
149	        transform: scale(0.97);
150	      }
151	      .circle.color-changed svg {
152	        animation: pulse 0.5s ease-out;
153	      }
154	    }
155	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
156	      .circle:hover:not(:active) svg {
157	        transform: scale(1.05);
158	      }
159	    }
160	    .visually-hidden {
161	      position: absolute;
162	      width: 1px;
163	      height: 1px;
164	      overflow: hidden;
165	      clip-path: inset(50%);
166	      white-space: nowrap;
167	    }
168	    .status {
169	      margin-top: 2rem;
170	      font-weight: 600;
171	    }
172	    .hint {
173	      margin-top: 0.25rem;
174	      font-size: 0.875rem;
175	      line-height: 1.75;
176	      text-wrap: balance;
177	    }
178	    .help-button {
179	      margin-left: 0.5rem;
180	      display: inline-block;
181	      width: 1.5rem;
182	      height: 1.5rem;
183	      border-radius: 50%;
184	      background: var(--kbd-bg);
185	      border: 1px solid var(--text);
186	      color: var(--text);
187	      cursor: pointer;
188	      font: inherit;
189	      font-size: 0.75rem;
190	      font-weight: bold;
191	      line-height: 1;
192	      text-align: center;
193	      vertical-align: middle;
194	      touch-action: manipulation;
195	      transition: background-color 0.2s, color 0.2s;
196	    }
197	    .help-button:focus-visible {
198	      outline: 2px solid currentColor;
199	      outline-offset: 2px;
200	    }
201	    @media (hover: hover) {
202	      .help-button:hover {
203	        background: var(--text);
204	        color: var(--bg);
205	      }
206	    }
207	    .keys {
208	      display: none;
209	    }
210	    .keys.visible {
211	      display: inline;
212	    }
213	    @media (hover: none) and (pointer: coarse) {
214	      .hint .keys {
215	        display: none !important;
216	      }
217	      .help-button {
218	        display: none;
219	      }
220	    }
221	    kbd {
222	      display: inline-block;
223	      padding: 0.125rem 0.375rem;
224	      background: var(--kbd-bg);
225	      border: 1px solid transparent;
226	      border-radius: 0.25rem;
227	      font-family: monospace;
228	      font-size: 0.75em;
229	      line-height: 1.2;
230	    }
231	  </style>
232	</head>
233	<body>
234	  <main>
235	    <h1 class="visually-hidden">Animated Circle</h1>
236	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
237	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
238	        <circle cx="50" cy="50" r="50" fill="currentColor" stroke="none"/>
239	      </svg>
240	    </button>
241	    <p class="status" id="status" role="status" aria-live="polite">Blue</p>
242	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> or hold to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
243	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
244	  </main>
245	  <script>
246	    const config = {
247	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
248	      storageKey: 'circle-color',
249	      hapticDuration: 50,
250	      longPressDuration: 500,
251	      longPressTolerance: 10,
252	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
253	    };
254	
255	    const DOM = {
256	      button: document.querySelector('.circle'),
257	      status: document.querySelector('.status'),
258	      helpButton: document.querySelector('.help-button'),
259	      keyHint: document.querySelector('.keys'),
260	      verbSpan: document.querySelector('.verb'),
261	      doubleVerbSpan: document.querySelector('.double-verb'),
262	    };
263	
264	    const state = {
265	      index: 0,
266	      shiftHeld: false,
267	      hoverCapable: true,
268	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
269	      hoverQuery: matchMedia('(hover: none)'),
270	      longPressTimer: null,
271	      longPressed: false,
272	      pressX: 0,
273	      pressY: 0,
274	      pointerType: '',
275	    };
276	
277	    function loadColor() {
278	      try {
279	        return localStorage.getItem(config.storageKey);
280	      } catch {
281	        return null;
282	      }
283	    }
284	
285	    function saveColor(color) {
286	      try {
287	        localStorage.setItem(config.storageKey, color);
288	      } catch {}
289	    }
290	
291	    function applyColor() {
292	      const color = config.colors[state.index];
293	      // The first color is the :root default, so it needs no attribute
294	      if (state.index === 0) delete DOM.button.dataset.color;
295	      else DOM.button.dataset.color = color;
296	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
297	    }
298	
299	    function syncFromStorage(color = loadColor()) {
300	      const index = config.colors.indexOf(color);
301	      state.index = index === -1 ? 0 : index;
302	      applyColor();
303	    }
304	
305	    // acknowledge: give feedback even when the color is already the requested one
306	    function setIndex(next, { haptic = false, acknowledge = false } = {}) {
307	      const changed = next !== state.index;
308	      if (!changed && !acknowledge) return;
309	      if (changed) {
310	        state.index = next;
311	        applyColor();
312	        saveColor(config.colors[state.index]);
313	      }
314	
315	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
316	
317	      if (state.reducedMotion.matches) return;
318	      DOM.button.classList.remove('color-changed');
319	      void DOM.button.offsetWidth;
320	      DOM.button.classList.add('color-changed');
321	    }
322	
323	    function changeColor(step) {
324	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
325	    }
326	
327	    function updateDeviceVerbs() {
328	      state.hoverCapable = !state.hoverQuery.matches;
329	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
330	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
331	    }
332	
333	    function toggleKeyHintVisibility() {
334	      const expanded = DOM.keyHint.classList.toggle('visible');
335	      DOM.helpButton.setAttribute('aria-expanded', expanded);
336	    }
337	
338	    function syncKeyHint() {
339	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
340	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
341	    }
342	
343	    function handleKeyDown(event) {
344	      if (event.key === 'Enter' || event.key === ' ') {
345	        if (!event.repeat) state.shiftHeld = event.shiftKey;
346	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
347	        return;
348	      }
349	
350	      if (event.altKey || event.ctrlKey || event.metaKey) return;
351	
352	      if (event.key in config.keySteps) {
353	        event.preventDefault();
354	        changeColor(config.keySteps[event.key]);
355	      } else if (event.key === 'Home') {
356	        event.preventDefault();
357	        setIndex(0, { haptic: true });
358	      } else if (event.key === 'End') {
359	        event.preventDefault();
360	        setIndex(config.colors.length - 1, { haptic: true });
361	      }
362	    }
363	
364	    function handleEscape(event) {
365	      if (event.key !== 'Escape' || event.defaultPrevented) return;
366	      if (DOM.keyHint.classList.contains('visible')) toggleKeyHintVisibility();
367	    }
368	
369	    // Initialize
370	    syncFromStorage();
371	
372	    // Wait two frames to ensure layout is complete before enabling transitions
373	    requestAnimationFrame(() => requestAnimationFrame(() => {
374	      DOM.button.classList.remove('no-transition');
375	    }));
376	
377	    updateDeviceVerbs();
378	    syncKeyHint();
379	    // e.g. a tablet gaining or losing a trackpad/keyboard
380	    state.hoverQuery.addEventListener('change', () => {
381	      updateDeviceVerbs();
382	      syncKeyHint();
383	    });
384	
385	    // Event listeners
386	    function clearLongPressTimer() {
387	      if (state.longPressTimer) clearTimeout(state.longPressTimer);
388	      state.longPressTimer = null;
389	    }
390	
391	    function attachEventListeners() {
392	      DOM.button.addEventListener('keydown', handleKeyDown);
393	      DOM.button.addEventListener('keyup', (event) => {
394	        if (event.key === ' ') state.shiftHeld = event.shiftKey;
395	      });
396	      DOM.button.addEventListener('blur', () => {
397	        state.shiftHeld = false;
398	        clearLongPressTimer();
399	      });
400	      DOM.button.addEventListener('pointerdown', (event) => {
401	        clearLongPressTimer();
402	        state.longPressed = false;
403	        state.pointerType = event.pointerType;
404	        if (!event.isPrimary || event.button !== 0) return;
405	        state.pressX = event.clientX;
406	        state.pressY = event.clientY;
407	        state.longPressTimer = setTimeout(() => {
408	          state.longPressTimer = null;
409	          state.longPressed = true;
410	          setIndex(0, { haptic: true, acknowledge: true });
411	        }, config.longPressDuration);
412	      }, { passive: true });
413	      // Touch pointers are captured, so a finger sliding away never fires pointerleave
414	      DOM.button.addEventListener('pointermove', (event) => {
415	        if (!state.longPressTimer) return;
416	        const distance = Math.hypot(event.clientX - state.pressX, event.clientY - state.pressY);
417	        if (distance > config.longPressTolerance) clearLongPressTimer();
418	      }, { passive: true });
419	      DOM.button.addEventListener('contextmenu', (event) => {
420	        if (state.pointerType === 'mouse') {
421	          clearLongPressTimer();
422	        } else if (state.longPressTimer || state.longPressed) {
423	          event.preventDefault();
424	        }
425	      });
426	      DOM.button.addEventListener('pointerup', clearLongPressTimer, { passive: true });
427	      DOM.button.addEventListener('pointercancel', clearLongPressTimer, { passive: true });
428	      DOM.button.addEventListener('pointerleave', clearLongPressTimer, { passive: true });
429	      DOM.button.addEventListener('click', (event) => {
430	        clearLongPressTimer();
431	        const afterLongPress = state.longPressed && event.detail !== 0;
432	        state.longPressed = false;
433	        const reverse = event.shiftKey || state.shiftHeld;
434	        state.shiftHeld = false;
435	        // Only the second click of a run belongs to dblclick; later ones cycle again
436	        if (afterLongPress || event.detail === 2) return;
437	        changeColor(reverse ? -1 : 1);
438	      });
439	      DOM.button.addEventListener('dblclick', (event) => {
440	        // Some engines fire dblclick again on every even click of a run
441	        if (event.detail > 2) return;
442	        setIndex(0, { haptic: true, acknowledge: true });
443	      });
444	      DOM.button.addEventListener('animationend', () => {
445	        DOM.button.classList.remove('color-changed');
446	      });
447	
448	      DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
449	      addEventListener('keydown', handleEscape);
450	    }
451	
452	    attachEventListeners();
453	
454	    addEventListener('storage', (event) => {
455	      // Sync if changed key matches or if entire storage was cleared (key === null)
456	      if (event.key !== config.storageKey && event.key !== null) return;
457	      syncFromStorage(event.newValue);
458	    });
459	    // Storage events are not delivered while the page sits in the bfcache
460	    addEventListener('pageshow', (event) => {
461	      if (event.persisted) syncFromStorage();
462	    });
463	  </script>
464	</body>
465	</html>
